    ensures always(p.and(q)) == always(p).and(always(q)),
{
    let a = always(p.and(q));
    let b = always(p).and(always(q));

    // a entails b
    assert(a.entails(b)) by {
        assert(forall |ex: Execution<T>| a.satisfied_by(ex) ==> b.satisfied_by(ex)) by {
            forall |ex: Execution<T>| {
