pub proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
    requires
        p.entails(q),
        q.entails(p),
    ensures p == q,
{
    // From entailment both ways, get pointwise equivalence of `satisfied_by`.
    assert forall |ex: Execution<T>| p.satisfied_by(ex) ==> q.satisfied_by(ex) by {
        // p.entails(q) = valid(p.implies(q)) = forall ex, p.satisfied_by(ex) ==> q.satisfied_by(ex)
        reveal(TempPred::implies);
        reveal(valid);
        reveal(TempPred::entails);
        assert(p.entails(q));
    };

    assert forall |ex: Execution<T>| q.satisfied_by(ex) ==> p.satisfied_by(ex) by {
        assert(q.entails(p));
    };

    // Now the two predicates are equal at all points, hence the `TempPred` values are equal.
    // Since `TempPred` has a single field `pred`, its equality follows from extensionality
    // of `spec_fn`.
    assert forall |ex: Execution<T>| p.satisfied_by(ex) == q.satisfied_by(ex) by {
        forall |ex: Execution<T>| {
            if p.satisfied_by(ex) {
                assert(q.satisfied_by(ex));
            };
            if q.satisfied_by(ex) {
                assert(p.satisfied_by(ex));
            };
        };
    };
    assert p.pred == q.pred by {
        assert forall |ex: Execution<T>| p.pred(ex) == q.pred(ex);
    };
    assert(p == q);
}

