use vstd::prelude::*;

fn main() {}

verus!{

// File: defs.rs
pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }

}


#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {

    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred { pred: pred }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn and(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) && other.satisfied_by(ex))
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }

}


pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
proof fn always_unfold<T>(ex: Execution<T>, p: TempPred<T>)
    requires always(p).satisfied_by(ex),
    ensures forall |i: nat| p.satisfied_by(#[trigger] ex.suffix(i)),
{
    // `always(p).satisfied_by(ex)` is definitionally `forall i, p.satisfied_by(ex.suffix(i))`.
    assert forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i)) by {
        assert(always(p).satisfied_by(ex));
    };
}

proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
    requires
        p.entails(q),
        q.entails(p),
    ensures p == q,
{
    // Prove mutual implication of the predicates at every execution.
    assert forall |ex: Execution<T>| p.satisfied_by(ex) ==> q.satisfied_by(ex) by {
        assert(p.entails(q));
    };
    assert forall |ex: Execution<T>| q.satisfied_by(ex) ==> p.satisfied_by(ex) by {
        assert(q.entails(p));
    };

    // Then `p.satisfied_by(ex)` and `q.satisfied_by(ex)` are equal for all `ex`.
    assert forall |ex: Execution<T>| p.satisfied_by(ex) == q.satisfied_by(ex) by {
        if p.satisfied_by(ex) {
            assert(q.satisfied_by(ex));
        }
        if q.satisfied_by(ex) {
            assert(p.satisfied_by(ex));
        }
    };

    assert(p.pred == q.pred);
    assert(p == q);
}

pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    let left = always(p.and(q));
    let right = always(p).and(always(q));

    // left.entails(right)
    assert left.entails(right) by {
        assert forall |ex: Execution<T>| left.satisfied_by(ex) ==> right.satisfied_by(ex) by {
            if left.satisfied_by(ex) {
                // From `forall i, (p.and(q)).satisfied_by(ex.suffix(i))` infer both `always(p)` and `always(q)`.
                assert forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i)) by {
                    assert(p.and(q).satisfied_by(ex.suffix(i)));
                    assert(p.satisfied_by(ex.suffix(i)));
                };
                assert forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i)) by {
                    assert(p.and(q).satisfied_by(ex.suffix(i)));
                    assert(q.satisfied_by(ex.suffix(i)));
                };

                assert(always(p).satisfied_by(ex));
                assert(always(q).satisfied_by(ex));
                assert(right.satisfied_by(ex));
            }
        };
    };

    // right.entails(left)
    assert right.entails(left) by {
        assert forall |ex: Execution<T>| right.satisfied_by(ex) ==> left.satisfied_by(ex) by {
            if right.satisfied_by(ex) {
                assert(always(p).satisfied_by(ex));
                assert(always(q).satisfied_by(ex));

                assert forall |i: nat| #[trigger] (p.and(q)).satisfied_by(ex.suffix(i)) by {
                    assert(p.satisfied_by(ex.suffix(i)));
                    assert(q.satisfied_by(ex.suffix(i)));
                    assert(p.and(q).satisfied_by(ex.suffix(i)));
                };

                assert(left.satisfied_by(ex));
            }
        };
    };

    temp_pred_equality(left, right);
}


}
